using System.Net;
using System.Text.Json;
using HumanOS.Contracts.Family;
using HumanOS.Services.Family;
using Microsoft.Azure.Functions.Worker;
using Microsoft.Azure.Functions.Worker.Http;

namespace HumanOS.AzureFunctions.Api.Family;

/// <summary>
/// POST /family/capabilities/{capabilityId}/content
/// Saves course/pedagogical modules generated by the AI agent for a specific capability.
/// </summary>
public sealed class SaveCapabilityLearningContentFunction
{
    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };
    private readonly FamilyCapabilityService _capabilityService;

    public SaveCapabilityLearningContentFunction(FamilyCapabilityService capabilityService)
    {
        _capabilityService = capabilityService;
    }

    [Function("SaveCapabilityLearningContent")]
    public async Task<HttpResponseData> RunAsync(
        [HttpTrigger(AuthorizationLevel.Anonymous, "post", Route = "family/capabilities/{capabilityId:guid}/content")]
        HttpRequestData request,
        Guid capabilityId,
        CancellationToken cancellationToken)
    {
        SaveCapabilityLearningContentRequest? body;
        try
        {
            body = await JsonSerializer.DeserializeAsync<SaveCapabilityLearningContentRequest>(request.Body, JsonOptions, cancellationToken);
        }
        catch (JsonException)
        {
            return await FunctionResponseFactory.ErrorResponseAsync(
                request, HttpStatusCode.BadRequest, "InvalidJson", "The request body contains invalid JSON.", cancellationToken);
        }

        if (body is null || string.IsNullOrWhiteSpace(body.ModuleTitle))
        {
            return await FunctionResponseFactory.ErrorResponseAsync(
                request, HttpStatusCode.BadRequest, "MissingRequiredFields", "ModuleTitle and PedagogicalGoal are required.", cancellationToken);
        }

        body.CapabilityId = capabilityId;

        try
        {
            var contentId = await _capabilityService.SaveLearningContentAsync(body, cancellationToken);
            return await FunctionResponseFactory.CreatedResponseAsync(request, new { contentId, capabilityId }, cancellationToken);
        }
        catch (Exception ex)
        {
            return await FunctionResponseFactory.ErrorResponseAsync(
                request, HttpStatusCode.InternalServerError, "SaveFailed", ex.Message, cancellationToken);
        }
    }
}
